KIND = "atlas"
SYSTEM = "muscular"
E = {
"m-pectoralis-minor": {
"en": ["Pectoralis minor", "A thin triangular muscle beneath pectoralis major. It is an important landmark because it divides the axillary artery into three parts.",
 ["Outer surfaces of ribs 3–5 (near their cartilages)", "Coracoid process of the scapula", "Medial pectoral nerve (C8–T1)", "Pectoral branch of the thoraco-acromial artery",
  "Draws the scapula forwards and downwards; with the scapula fixed it raises the ribs to assist inspiration"], [],
 ["Shortening of the muscle can compress the brachial plexus and axillary vessels beneath the coracoid process (pectoralis minor syndrome)."],
 ["Pectoralis minor attaches to the coracoid process; it divides the axillary lymph nodes into three levels.", "The cords of the brachial plexus and the axillary artery pass beneath pectoralis minor; they may be compressed in hyperabduction."], ["subclavius"]],
"fr": ["Muscle petit pectoral", "Muscle mince et triangulaire situé sous le grand pectoral. C'est un repère important car il divise l'artère axillaire en trois segments.",
 ["Face externe des côtes 3 à 5 (près de leurs cartilages)", "Processus coracoïde de la scapula", "Nerf pectoral médial (C8–T1)", "Rameau pectoral de l'artère thoraco-acromiale",
  "Abaisse la scapula et la porte en avant ; scapula fixée, il élève les côtes et aide l'inspiration"], [],
 ["Un raccourcissement du muscle peut comprimer le plexus brachial et les vaisseaux axillaires sous le processus coracoïde (syndrome du petit pectoral)."],
 ["Le petit pectoral s'insère sur le processus coracoïde ; il divise les nœuds lymphatiques axillaires en trois niveaux.", "Les faisceaux du plexus brachial et l'artère axillaire passent sous le petit pectoral ; ils peuvent être comprimés en hyperabduction."], ["subclavier"]],
"de": ["M. pectoralis minor", "Dünner dreieckiger Muskel unter dem Pectoralis major. Er ist ein wichtiger Orientierungspunkt, weil er die A. axillaris in drei Abschnitte teilt.",
 ["Außenfläche der 3.–5. Rippe (nahe den Knorpeln)", "Processus coracoideus scapulae", "N. pectoralis medialis (C8–T1)", "R. pectoralis der A. thoracoacromialis",
  "Zieht das Schulterblatt nach vorn unten; bei fixiertem Schulterblatt hebt er die Rippen und unterstützt die Einatmung"], [],
 ["Eine Verkürzung des Muskels kann Plexus brachialis und Achselgefäße unter dem Processus coracoideus einengen (Pectoralis-minor-Syndrom)."],
 ["Der Pectoralis minor setzt am Processus coracoideus an; er teilt die axillären Lymphknoten in drei Level.", "Unter dem Pectoralis minor ziehen die Faszikel des Plexus brachialis und die A. axillaris; bei Hyperabduktion können sie eingeengt werden."], ["Subclavius", "kleiner Brustmuskel"]],
"es": ["Músculo pectoral menor", "Músculo fino y triangular situado bajo el pectoral mayor. Es un punto de referencia importante porque divide la arteria axilar en tres porciones.",
 ["Cara externa de las costillas 3.ª–5.ª (cerca de sus cartílagos)", "Apófisis coracoides de la escápula", "Nervio pectoral medial (C8–T1)", "Rama pectoral de la arteria toracoacromial",
  "Lleva la escápula hacia delante y abajo; con la escápula fija eleva las costillas y ayuda a la inspiración"], [],
 ["El acortamiento del músculo puede comprimir el plexo braquial y los vasos axilares bajo la apófisis coracoides (síndrome del pectoral menor)."],
 ["El pectoral menor se inserta en la apófisis coracoides; divide los ganglios linfáticos axilares en tres niveles.", "Bajo el pectoral menor pasan los fascículos del plexo braquial y la arteria axilar; pueden comprimirse en la hiperabducción."], ["subclavio"]],
},
"m-serratus-anterior": {
"en": ["Serratus anterior", "A broad muscle on the side of the chest wall that attaches to the ribs like the teeth of a saw. It holds the scapula against the chest wall.",
 ["Outer surfaces of ribs 1–8/9", "Anterior (costal) surface of the medial border of the scapula, especially the inferior angle", "Long thoracic nerve (C5–C7)", "Lateral thoracic artery, thoracodorsal artery",
  "Protracts the scapula (punching) and rotates it upwards so the arm can be raised above the head; holds the scapula on the chest wall"], [],
 ["Injury to the long thoracic nerve during axillary lymph node dissection causes a winged scapula; when the patient pushes against a wall the medial border of the scapula lifts away clearly."],
 ["Serratus anterior is known as the boxer's muscle; it draws the scapula forwards when punching.", "It works with trapezius to rotate the scapula upwards; when paralysed the arm cannot be raised above 90°."], ["serratus"]],
"fr": ["Muscle dentelé antérieur", "Large muscle de la paroi latérale du thorax qui s'insère sur les côtes comme les dents d'une scie. Il plaque la scapula contre la paroi thoracique.",
 ["Face externe des côtes 1 à 8/9", "Face antérieure (costale) du bord médial de la scapula, surtout l'angle inférieur", "Nerf thoracique long (C5–C7)", "Artère thoracique latérale, artère thoraco-dorsale",
  "Porte la scapula en avant (coup de poing) et la fait tourner vers le haut pour lever le bras au-dessus de la tête ; maintient la scapula contre le thorax"], [],
 ["Une lésion du nerf thoracique long lors d'un curage axillaire provoque une scapula alata ; quand le patient pousse contre un mur, le bord médial de la scapula se décolle nettement."],
 ["Le dentelé antérieur est le « muscle du boxeur » ; il porte la scapula en avant lors du coup de poing.", "Il agit avec le trapèze dans la rotation vers le haut de la scapula ; s'il est paralysé, le bras ne peut dépasser 90°."], ["grand dentelé", "dentelé"]],
"de": ["M. serratus anterior", "Breiter Muskel an der seitlichen Brustwand, der wie Sägezähne an den Rippen entspringt. Er hält das Schulterblatt am Brustkorb.",
 ["Außenfläche der 1.–8./9. Rippe", "Vorderfläche (Facies costalis) des Margo medialis scapulae, v. a. Angulus inferior", "N. thoracicus longus (C5–C7)", "A. thoracica lateralis, A. thoracodorsalis",
  "Zieht das Schulterblatt nach vorn (Faustschlag) und dreht es nach oben, sodass der Arm über den Kopf gehoben werden kann; hält es am Brustkorb"], [],
 ["Eine Verletzung des N. thoracicus longus bei der axillären Lymphknotendissektion verursacht eine Scapula alata; drückt der Patient gegen eine Wand, hebt sich der mediale Schulterblattrand deutlich ab."],
 ["Der Serratus anterior gilt als Boxermuskel; er zieht beim Faustschlag das Schulterblatt nach vorn.", "Er dreht zusammen mit dem Trapezius das Schulterblatt nach oben; bei Lähmung kann der Arm nicht über 90° gehoben werden."], ["Serratus", "Sägemuskel"]],
"es": ["Músculo serrato anterior", "Músculo ancho de la pared lateral del tórax que se fija a las costillas como los dientes de una sierra. Mantiene la escápula contra la pared torácica.",
 ["Cara externa de las costillas 1.ª–8.ª/9.ª", "Cara anterior (costal) del borde medial de la escápula, sobre todo el ángulo inferior", "Nervio torácico largo (C5–C7)", "Arteria torácica lateral, arteria toracodorsal",
  "Protruye la escápula (dar un puñetazo) y la rota hacia arriba para elevar el brazo por encima de la cabeza; mantiene la escápula sobre el tórax"], [],
 ["La lesión del nervio torácico largo en el vaciamiento axilar produce escápula alada; al empujar contra una pared el borde medial de la escápula se separa claramente."],
 ["El serrato anterior es el «músculo del boxeador»; lleva la escápula hacia delante al golpear.", "Rota la escápula hacia arriba junto con el trapecio; si se paraliza el brazo no puede elevarse por encima de 90°."], ["serrato"]],
},
"mm-intercostales": {
"en": ["Intercostal muscles", "A three-layered group of muscles filling the spaces between the ribs. The fibres of the outer layer run downwards and forwards, those of the inner layer downwards and backwards.",
 ["Lower border of the rib above", "Upper border of the rib below", "Intercostal nerves (T1–T11)", "Anterior and posterior intercostal arteries",
  "External: raise the ribs to assist inspiration; internal and innermost: pull the ribs down in forced expiration; all strengthen the intercostal space"],
 [["Neurovascular bundle", "The intercostal vein, artery and nerve (VAN from above down) run between internal and innermost intercostals in the costal groove on the lower border of the rib."]],
 ["Pleural tap is performed just above the upper border of the lower rib to protect the neurovascular bundle.", "Intercostal nerve block is used for the pain of rib fractures."],
 ["External intercostal fibres run downwards and forwards ('hands in pockets'), internal intercostal fibres downwards and backwards.", "External intercostals act in inspiration, the interosseous part of the internal intercostals in forced expiration."], ["intercostal"]],
"fr": ["Muscles intercostaux", "Groupe de muscles en trois couches qui comblent les espaces entre les côtes. Les fibres de la couche externe vont en bas et en avant, celles de la couche interne en bas et en arrière.",
 ["Bord inférieur de la côte sus-jacente", "Bord supérieur de la côte sous-jacente", "Nerfs intercostaux (T1–T11)", "Artères intercostales antérieures et postérieures",
  "Externes : élèvent les côtes et aident l'inspiration ; internes et intimes : abaissent les côtes en expiration forcée ; tous renforcent l'espace intercostal"],
 [["Pédicule vasculo-nerveux", "La veine, l'artère et le nerf intercostaux (VAN de haut en bas) cheminent entre les intercostaux internes et intimes, dans le sillon costal du bord inférieur de la côte."]],
 ["La ponction pleurale se fait au bord supérieur de la côte inférieure pour épargner le pédicule vasculo-nerveux.", "Le bloc des nerfs intercostaux est utilisé contre la douleur des fractures de côtes."],
 ["Les fibres des intercostaux externes vont en bas et en avant (« mains dans les poches »), celles des internes en bas et en arrière.", "Les intercostaux externes agissent en inspiration, la partie interosseuse des internes en expiration forcée."], ["intercostal"]],
"de": ["Mm. intercostales", "Dreischichtige Muskelgruppe, die die Räume zwischen den Rippen ausfüllt. Die Fasern der äußeren Schicht verlaufen nach vorn unten, die der inneren nach hinten unten.",
 ["Unterrand der oberen Rippe", "Oberrand der unteren Rippe", "Nn. intercostales (T1–T11)", "Aa. intercostales anteriores und posteriores",
  "Externi: heben die Rippen und unterstützen die Einatmung; interni und intimi: senken die Rippen bei forcierter Ausatmung; alle festigen den Zwischenrippenraum"],
 [["Gefäß-Nerven-Straße", "V., A. und N. intercostalis (von oben nach unten VAN) verlaufen zwischen M. intercostalis internus und intimus im Sulcus costae am Unterrand der Rippe."]],
 ["Die Pleurapunktion erfolgt am Oberrand der unteren Rippe, um die Gefäß-Nerven-Straße zu schonen.", "Die Interkostalblockade wird bei Schmerzen durch Rippenbrüche eingesetzt."],
 ["Die Fasern der Mm. intercostales externi verlaufen nach vorn unten („Hände in den Hosentaschen“), die der interni nach hinten unten.", "Die externi wirken bei der Einatmung, der interossäre Teil der interni bei forcierter Ausatmung."], ["Interkostalmuskeln", "Zwischenrippenmuskeln"]],
"es": ["Músculos intercostales", "Grupo de músculos en tres capas que ocupa los espacios entre las costillas. Las fibras de la capa externa van hacia abajo y adelante; las de la interna, hacia abajo y atrás.",
 ["Borde inferior de la costilla superior", "Borde superior de la costilla inferior", "Nervios intercostales (T1–T11)", "Arterias intercostales anteriores y posteriores",
  "Externos: elevan las costillas y ayudan a la inspiración; internos e íntimos: descienden las costillas en la espiración forzada; todos refuerzan el espacio intercostal"],
 [["Paquete vasculonervioso", "La vena, la arteria y el nervio intercostales (VAN de arriba abajo) discurren entre los intercostales internos e íntimos, en el surco costal del borde inferior de la costilla."]],
 ["La toracocentesis se hace por el borde superior de la costilla inferior para proteger el paquete vasculonervioso.", "El bloqueo intercostal se usa para el dolor de las fracturas costales."],
 ["Las fibras de los intercostales externos van hacia abajo y adelante («manos en los bolsillos»); las de los internos, hacia abajo y atrás.", "Los externos actúan en la inspiración; la porción interósea de los internos, en la espiración forzada."], ["intercostal"]],
},
"diaphragma": {
"en": ["Diaphragm", "The dome-shaped musculotendinous sheet separating the thoracic and abdominal cavities. It is the most important muscle of respiration; at its centre lies a trefoil-shaped tendon (central tendon).",
 ["Sternal part: back of the xiphoid process; costal part: inner surfaces of costal cartilages 7–12; lumbar part: right crus (L1–L3) and left crus (L1–L2), medial and lateral arcuate ligaments",
  "Central tendon", "Phrenic nerve (C3–C5) – motor; the periphery receives sensory fibres from the lower intercostal nerves",
  "Superior and inferior phrenic arteries, pericardiacophrenic artery, musculophrenic artery",
  "On contraction the dome flattens, the vertical diameter of the thorax increases and air enters the lungs (inspiration); by raising intra-abdominal pressure it aids defecation, micturition and childbirth"],
 [["Openings", "Caval opening (T8): inferior vena cava and branches of the right phrenic nerve; oesophageal hiatus (T10): oesophagus and vagus nerves; aortic hiatus (T12): aorta, thoracic duct and azygos vein. Memory aid: 'I 8 10 eggs at 12' (IVC 8, oesophagus 10, aorta 12)."]],
 ["In a hiatus hernia part of the stomach passes through the oesophageal hiatus into the chest.",
  "Irritation of the diaphragm (e.g. splenic rupture, cholecystitis) causes pain referred to the shoulder via the phrenic nerve (C3–C5 dermatomes).",
  "High spinal cord injuries (above C3) cause diaphragmatic paralysis and respiratory arrest: 'C3, 4, 5 keeps the diaphragm alive'."],
 ["The muscle fibres of the diaphragm arise from sternal, costal and lumbar (crural) parts and insert into the central tendon.", "Bochdalek hernia (posterolateral, left) and Morgagni hernia (anterior, right) are congenital diaphragmatic hernias."], ["diaphragm"]],
"fr": ["Diaphragme", "Cloison musculo-tendineuse en forme de dôme qui sépare les cavités thoracique et abdominale. C'est le principal muscle respiratoire ; en son centre se trouve un tendon en trèfle (centre tendineux).",
 ["Partie sternale : face postérieure du processus xiphoïde ; partie costale : face interne des cartilages costaux 7 à 12 ; partie lombaire : pilier droit (L1–L3) et pilier gauche (L1–L2), ligaments arqués médial et latéral",
  "Centre tendineux", "Nerf phrénique (C3–C5) – moteur ; la périphérie reçoit une sensibilité des nerfs intercostaux inférieurs",
  "Artères phréniques supérieures et inférieures, artère péricardiaco-phrénique, artère musculo-phrénique",
  "En se contractant, le dôme s'abaisse, le diamètre vertical du thorax augmente et l'air entre dans les poumons (inspiration) ; en augmentant la pression abdominale, il aide la défécation, la miction et l'accouchement"],
 [["Orifices", "Foramen de la veine cave (T8) : veine cave inférieure et branches du nerf phrénique droit ; hiatus œsophagien (T10) : œsophage et nerfs vagues ; hiatus aortique (T12) : aorte, conduit thoracique et veine azygos. Moyen mnémotechnique : 8–10–12 (VCI, œsophage, aorte)."]],
 ["Dans la hernie hiatale, une partie de l'estomac passe dans le thorax par le hiatus œsophagien.",
  "Une irritation diaphragmatique (rupture splénique, cholécystite) donne une douleur projetée à l'épaule par le nerf phrénique (dermatomes C3–C5).",
  "Les lésions médullaires hautes (au-dessus de C3) paralysent le diaphragme et entraînent un arrêt respiratoire : « C3, C4, C5 maintiennent le diaphragme en vie »."],
 ["Les fibres musculaires du diaphragme naissent des parties sternale, costale et lombaire (piliers) et se terminent sur le centre tendineux.", "La hernie de Bochdalek (postéro-latérale gauche) et celle de Morgagni (antérieure droite) sont des hernies diaphragmatiques congénitales."], ["diaphragme"]],
"de": ["Zwerchfell", "Kuppelförmige Muskel-Sehnen-Platte, die Brust- und Bauchhöhle trennt. Es ist der wichtigste Atemmuskel; in seiner Mitte liegt eine kleeblattförmige Sehnenplatte (Centrum tendineum).",
 ["Pars sternalis: Rückfläche des Processus xiphoideus; Pars costalis: Innenfläche der Rippenknorpel 7–12; Pars lumbalis: Crus dextrum (L1–L3) und Crus sinistrum (L1–L2), Lig. arcuatum mediale und laterale",
  "Centrum tendineum", "N. phrenicus (C3–C5) – motorisch; die Peripherie wird sensibel von den unteren Nn. intercostales versorgt",
  "Aa. phrenicae superiores und inferiores, A. pericardiacophrenica, A. musculophrenica",
  "Bei Kontraktion flacht die Kuppel ab, der vertikale Thoraxdurchmesser nimmt zu und Luft strömt in die Lunge (Einatmung); durch Erhöhung des Bauchdrucks unterstützt es Defäkation, Miktion und Geburt"],
 [["Öffnungen", "Foramen venae cavae (T8): V. cava inferior und Äste des rechten N. phrenicus; Hiatus oesophageus (T10): Ösophagus und Nn. vagi; Hiatus aorticus (T12): Aorta, Ductus thoracicus und V. azygos. Merkhilfe: 8–10–12 (Hohlvene, Speiseröhre, Aorta)."]],
 ["Bei der Hiatushernie tritt ein Teil des Magens durch den Hiatus oesophageus in den Brustraum.",
  "Eine Reizung des Zwerchfells (z. B. Milzruptur, Cholezystitis) verursacht über den N. phrenicus in die Schulter ausstrahlende Schmerzen (Dermatome C3–C5).",
  "Hohe Rückenmarksverletzungen (oberhalb C3) führen zu Zwerchfelllähmung und Atemstillstand: „C3, 4, 5 hält das Zwerchfell am Leben“."],
 ["Die Muskelfasern des Zwerchfells entspringen aus Pars sternalis, costalis und lumbalis (Crura) und setzen am Centrum tendineum an.", "Bochdalek-Hernie (hinten links) und Morgagni-Hernie (vorn rechts) sind angeborene Zwerchfellhernien."], ["Diaphragma"]],
"es": ["Diafragma", "Lámina musculotendinosa en forma de cúpula que separa las cavidades torácica y abdominal. Es el músculo respiratorio más importante; en su centro hay un tendón en forma de trébol (centro tendinoso).",
 ["Porción esternal: cara posterior de la apófisis xifoides; costal: cara interna de los cartílagos costales 7.º–12.º; lumbar: pilar derecho (L1–L3) y pilar izquierdo (L1–L2), ligamentos arqueados medial y lateral",
  "Centro tendinoso", "Nervio frénico (C3–C5) – motor; la periferia recibe sensibilidad de los nervios intercostales inferiores",
  "Arterias frénicas superiores e inferiores, arteria pericardiofrénica, arteria musculofrénica",
  "Al contraerse la cúpula se aplana, aumenta el diámetro vertical del tórax y el aire entra en los pulmones (inspiración); al elevar la presión abdominal ayuda a la defecación, la micción y el parto"],
 [["Orificios", "Orificio de la vena cava (T8): vena cava inferior y ramas del frénico derecho; hiato esofágico (T10): esófago y nervios vagos; hiato aórtico (T12): aorta, conducto torácico y vena ácigos. Regla: 8–10–12 (cava, esófago, aorta)."]],
 ["En la hernia de hiato parte del estómago pasa al tórax por el hiato esofágico.",
  "La irritación del diafragma (p. ej. rotura esplénica, colecistitis) produce dolor referido al hombro a través del frénico (dermatomas C3–C5).",
  "Las lesiones medulares altas (por encima de C3) paralizan el diafragma y causan paro respiratorio: «C3, 4 y 5 mantienen vivo el diafragma»."],
 ["Las fibras musculares del diafragma nacen de las porciones esternal, costal y lumbar (pilares) y se insertan en el centro tendinoso.", "Las hernias de Bochdalek (posterolateral izquierda) y de Morgagni (anterior derecha) son hernias diafragmáticas congénitas."], ["diafragma"]],
},
"m-rectus-abdominis": {
"en": ["Rectus abdominis", "A long muscle running vertically on either side of the midline of the anterior abdominal wall. Its 3–4 tendinous intersections give the 'six-pack' appearance.",
 ["Pubic crest and pubic symphysis", "Costal cartilages 5–7 and xiphoid process", "Intercostal nerves (T7–T11) and subcostal nerve (T12)",
  "Superior epigastric artery (internal thoracic artery) and inferior epigastric artery (external iliac artery)",
  "Flexes the trunk; raises intra-abdominal pressure; stabilises the pelvis against forward tilt"],
 [["Rectus sheath", "The muscle lies in a sheath formed by the aponeuroses of the lateral abdominal muscles. The posterior layer of the sheath is absent below the arcuate line, between the umbilicus and pubis."]],
 ["Separation of the two muscle bellies in the midline in pregnancy or obesity is called diastasis recti.", "Rupture of the inferior epigastric artery can cause a rectus sheath haematoma."],
 ["Rectus abdominis is divided by tendinous intersections ('six-pack'); these are attached to the anterior layer of the sheath.", "The superior and inferior epigastric arteries anastomose in the posterior wall of the sheath."], ["abs", "six-pack", "pyramidalis"]],
"fr": ["Muscle droit de l'abdomen", "Long muscle vertical de part et d'autre de la ligne médiane de la paroi abdominale antérieure. Ses 3–4 intersections tendineuses lui donnent l'aspect de « tablette de chocolat ».",
 ["Crête pubienne et symphyse pubienne", "Cartilages costaux 5 à 7 et processus xiphoïde", "Nerfs intercostaux (T7–T11) et nerf subcostal (T12)",
  "Artère épigastrique supérieure (artère thoracique interne) et artère épigastrique inférieure (artère iliaque externe)",
  "Fléchit le tronc ; augmente la pression intra-abdominale ; stabilise le bassin contre la bascule antérieure"],
 [["Gaine des droits", "Le muscle est contenu dans une gaine formée par les aponévroses des muscles larges de l'abdomen. Le feuillet postérieur de la gaine manque sous la ligne arquée, entre l'ombilic et le pubis."]],
 ["L'écartement des deux muscles sur la ligne médiane pendant la grossesse ou l'obésité s'appelle diastasis des grands droits.", "La rupture de l'artère épigastrique inférieure peut provoquer un hématome de la gaine des droits."],
 ["Le droit de l'abdomen est segmenté par des intersections tendineuses (« tablette de chocolat ») adhérentes au feuillet antérieur de la gaine.", "Les artères épigastriques supérieure et inférieure s'anastomosent dans la paroi postérieure de la gaine."], ["abdominaux", "grand droit", "pyramidal"]],
"de": ["M. rectus abdominis", "Langer Muskel, der beiderseits der Mittellinie der vorderen Bauchwand senkrecht verläuft. Seine 3–4 Zwischensehnen (Intersectiones tendineae) ergeben das „Sixpack“.",
 ["Crista pubica und Symphysis pubica", "Rippenknorpel 5–7 und Processus xiphoideus", "Nn. intercostales (T7–T11) und N. subcostalis (T12)",
  "A. epigastrica superior (A. thoracica interna) und A. epigastrica inferior (A. iliaca externa)",
  "Beugt den Rumpf; erhöht den Bauchdruck; stabilisiert das Becken gegen Vorkippen"],
 [["Rektusscheide", "Der Muskel liegt in einer Scheide aus den Aponeurosen der seitlichen Bauchmuskeln. Das hintere Blatt fehlt unterhalb der Linea arcuata zwischen Nabel und Schambein."]],
 ["Das Auseinanderweichen der beiden Muskelbäuche in der Mittellinie bei Schwangerschaft oder Adipositas heißt Rektusdiastase.", "Ein Riss der A. epigastrica inferior kann ein Rektusscheidenhämatom verursachen."],
 ["Der Rectus abdominis wird durch Intersectiones tendineae unterteilt („Sixpack“); diese sind mit dem vorderen Blatt der Scheide verwachsen.", "In der hinteren Wand der Scheide anastomosieren A. epigastrica superior und inferior."], ["gerader Bauchmuskel", "Sixpack", "Pyramidalis"]],
"es": ["Músculo recto del abdomen", "Músculo largo que discurre verticalmente a ambos lados de la línea media de la pared abdominal anterior. Sus 3–4 intersecciones tendinosas le dan el aspecto de «tableta».",
 ["Cresta del pubis y sínfisis del pubis", "Cartílagos costales 5.º–7.º y apófisis xifoides", "Nervios intercostales (T7–T11) y nervio subcostal (T12)",
  "Arteria epigástrica superior (arteria torácica interna) y arteria epigástrica inferior (arteria ilíaca externa)",
  "Flexiona el tronco; aumenta la presión intraabdominal; estabiliza la pelvis frente a la inclinación anterior"],
 [["Vaina de los rectos", "El músculo está dentro de una vaina formada por las aponeurosis de los músculos anchos del abdomen. La hoja posterior falta por debajo de la línea arqueada, entre el ombligo y el pubis."]],
 ["La separación de los dos vientres en la línea media en el embarazo o la obesidad se llama diástasis de rectos.", "La rotura de la arteria epigástrica inferior puede causar un hematoma de la vaina de los rectos."],
 ["El recto del abdomen está dividido por intersecciones tendinosas («tableta»), adheridas a la hoja anterior de la vaina.", "Las arterias epigástricas superior e inferior se anastomosan en la pared posterior de la vaina."], ["abdominales", "piramidal"]],
},
"m-obliquus-externus": {
"en": ["External oblique", "The most superficial and largest muscle of the lateral abdominal wall. Its fibres run from above and outside downwards and inwards (like hands in pockets).",
 ["Outer surfaces of ribs 5–12", "Linea alba, pubic tubercle and anterior half of the iliac crest; its lower border forms the inguinal ligament",
  "Intercostal nerves (T7–T11), subcostal nerve (T12), iliohypogastric nerve", "Posterior intercostal arteries, deep circumflex iliac artery",
  "Both sides: flex the trunk and raise intra-abdominal pressure; one side: bends the trunk to the same side and rotates it to the opposite side"],
 [["Inguinal canal", "Its aponeurosis forms the anterior wall of the inguinal canal; the slit in the aponeurosis is the superficial inguinal ring."]],
 ["Inguinal hernias develop through weak points in this region."],
 ["The external oblique fibres run 'hands in pockets' (downwards, forwards and medially); acting on one side it rotates the trunk to the opposite side.", "Its aponeurosis forms the inguinal ligament, the lacunar ligament and the superficial inguinal ring."], ["external oblique", "obliques"]],
"fr": ["Muscle oblique externe de l'abdomen", "Le plus superficiel et le plus grand des muscles de la paroi abdominale latérale. Ses fibres vont de haut et de dehors vers le bas et en dedans (comme des mains dans les poches).",
 ["Face externe des côtes 5 à 12", "Ligne blanche, tubercule pubien et moitié antérieure de la crête iliaque ; son bord inférieur forme le ligament inguinal",
  "Nerfs intercostaux (T7–T11), nerf subcostal (T12), nerf ilio-hypogastrique", "Artères intercostales postérieures, artère circonflexe iliaque profonde",
  "Bilatéral : fléchit le tronc et augmente la pression abdominale ; unilatéral : incline le tronc du même côté et le tourne du côté opposé"],
 [["Canal inguinal", "Son aponévrose forme la paroi antérieure du canal inguinal ; la fente de l'aponévrose est l'anneau inguinal superficiel."]],
 ["Les hernies inguinales se développent à travers les points faibles de cette région."],
 ["Les fibres de l'oblique externe vont « mains dans les poches » (en bas, en avant et en dedans) ; en contraction unilatérale il tourne le tronc du côté opposé.", "Son aponévrose forme le ligament inguinal, le ligament lacunaire et l'anneau inguinal superficiel."], ["grand oblique", "oblique externe"]],
"de": ["M. obliquus externus abdominis", "Der oberflächlichste und größte Muskel der seitlichen Bauchwand. Seine Fasern verlaufen von oben außen nach unten innen (wie Hände in den Hosentaschen).",
 ["Außenfläche der 5.–12. Rippe", "Linea alba, Tuberculum pubicum und vordere Hälfte der Crista iliaca; sein Unterrand bildet das Leistenband",
  "Nn. intercostales (T7–T11), N. subcostalis (T12), N. iliohypogastricus", "Aa. intercostales posteriores, A. circumflexa ilium profunda",
  "Beidseitig: beugt den Rumpf und erhöht den Bauchdruck; einseitig: neigt den Rumpf zur gleichen Seite und dreht ihn zur Gegenseite"],
 [["Leistenkanal", "Seine Aponeurose bildet die Vorderwand des Canalis inguinalis; der Schlitz in der Aponeurose ist der Anulus inguinalis superficialis."]],
 ["Leistenhernien entstehen an Schwachstellen dieser Region."],
 ["Die Fasern des äußeren schrägen Bauchmuskels verlaufen „Hände in die Taschen“ (nach unten vorn innen); einseitig dreht er den Rumpf zur Gegenseite.", "Seine Aponeurose bildet Lig. inguinale, Lig. lacunare und den äußeren Leistenring."], ["äußerer schräger Bauchmuskel", "Externus"]],
"es": ["Músculo oblicuo externo del abdomen", "El más superficial y grande de los músculos de la pared abdominal lateral. Sus fibras van de arriba y afuera hacia abajo y adentro (como las manos en los bolsillos).",
 ["Cara externa de las costillas 5.ª–12.ª", "Línea alba, tubérculo del pubis y mitad anterior de la cresta ilíaca; su borde inferior forma el ligamento inguinal",
  "Nervios intercostales (T7–T11), nervio subcostal (T12), nervio iliohipogástrico", "Arterias intercostales posteriores, arteria circunfleja ilíaca profunda",
  "Bilateral: flexiona el tronco y aumenta la presión abdominal; unilateral: inclina el tronco al mismo lado y lo rota al opuesto"],
 [["Conducto inguinal", "Su aponeurosis forma la pared anterior del conducto inguinal; la hendidura de la aponeurosis es el anillo inguinal superficial."]],
 ["Las hernias inguinales se desarrollan a través de los puntos débiles de esta región."],
 ["Las fibras del oblicuo externo van «manos en los bolsillos» (abajo, adelante y adentro); en contracción unilateral rota el tronco al lado opuesto.", "Su aponeurosis forma el ligamento inguinal, el lacunar y el anillo inguinal superficial."], ["oblicuo mayor", "oblicuo externo"]],
},
"m-obliquus-internus": {
"en": ["Internal oblique", "A muscle of the lateral abdominal wall lying beneath the external oblique, most of its fibres running at right angles to it.",
 ["Thoracolumbar fascia, anterior 2/3 of the iliac crest, lateral 2/3 of the inguinal ligament",
  "Lower borders of ribs 10–12, linea alba, pubic crest and pectineal line (via the conjoint tendon)",
  "Intercostal nerves (T7–T11), subcostal nerve, iliohypogastric and ilioinguinal nerves (L1)", "Inferior and superior epigastric arteries, deep circumflex iliac artery",
  "Both sides: flex the trunk and raise intra-abdominal pressure; one side: bends the trunk to the same side and rotates it to the same side"],
 [["Cremaster muscle", "In the male its lower fibres descend with the spermatic cord into the scrotum to form the cremaster muscle (genital branch of the genitofemoral nerve)."]], [],
 ["The internal oblique fibres run at right angles to the external oblique; acting on one side it rotates the trunk to the same side.", "The internal oblique forms the cremaster muscle and part of the conjoint tendon."], ["internal oblique", "obliques"]],
"fr": ["Muscle oblique interne de l'abdomen", "Muscle de la paroi abdominale latérale situé sous l'oblique externe, dont la plupart des fibres lui sont perpendiculaires.",
 ["Fascia thoraco-lombaire, 2/3 antérieurs de la crête iliaque, 2/3 latéraux du ligament inguinal",
  "Bord inférieur des côtes 10 à 12, ligne blanche, crête pubienne et ligne pectinée (par le tendon conjoint)",
  "Nerfs intercostaux (T7–T11), nerf subcostal, nerfs ilio-hypogastrique et ilio-inguinal (L1)", "Artères épigastriques inférieure et supérieure, artère circonflexe iliaque profonde",
  "Bilatéral : fléchit le tronc, augmente la pression abdominale ; unilatéral : incline le tronc et le tourne du même côté"],
 [["Muscle crémaster", "Chez l'homme, ses fibres inférieures descendent avec le cordon spermatique dans le scrotum pour former le muscle crémaster (rameau génital du nerf génito-fémoral)."]], [],
 ["Les fibres de l'oblique interne sont perpendiculaires à celles de l'oblique externe ; en contraction unilatérale il tourne le tronc du même côté.", "L'oblique interne forme le crémaster et une partie du tendon conjoint."], ["petit oblique", "oblique interne"]],
"de": ["M. obliquus internus abdominis", "Muskel der seitlichen Bauchwand unter dem äußeren schrägen Bauchmuskel; die meisten seiner Fasern verlaufen senkrecht zu diesem.",
 ["Fascia thoracolumbalis, vordere 2/3 der Crista iliaca, laterale 2/3 des Leistenbands",
  "Unterränder der 10.–12. Rippe, Linea alba, Crista pubica und Pecten ossis pubis (über die Falx inguinalis)",
  "Nn. intercostales (T7–T11), N. subcostalis, N. iliohypogastricus und N. ilioinguinalis (L1)", "A. epigastrica inferior und superior, A. circumflexa ilium profunda",
  "Beidseitig: beugt den Rumpf und erhöht den Bauchdruck; einseitig: neigt und dreht den Rumpf zur gleichen Seite"],
 [["M. cremaster", "Beim Mann ziehen seine unteren Fasern mit dem Samenstrang in den Hodensack und bilden den M. cremaster (R. genitalis des N. genitofemoralis)."]], [],
 ["Die Fasern des inneren schrägen Bauchmuskels verlaufen senkrecht zum äußeren; einseitig dreht er den Rumpf zur gleichen Seite.", "Der Internus bildet den M. cremaster und einen Teil der Falx inguinalis."], ["innerer schräger Bauchmuskel", "Internus"]],
"es": ["Músculo oblicuo interno del abdomen", "Músculo de la pared abdominal lateral situado bajo el oblicuo externo, con la mayoría de sus fibras perpendiculares a él.",
 ["Fascia toracolumbar, 2/3 anteriores de la cresta ilíaca, 2/3 laterales del ligamento inguinal",
  "Bordes inferiores de las costillas 10.ª–12.ª, línea alba, cresta del pubis y línea pectínea (mediante el tendón conjunto)",
  "Nervios intercostales (T7–T11), nervio subcostal, nervios iliohipogástrico e ilioinguinal (L1)", "Arterias epigástricas inferior y superior, arteria circunfleja ilíaca profunda",
  "Bilateral: flexiona el tronco y aumenta la presión abdominal; unilateral: inclina y rota el tronco hacia el mismo lado"],
 [["Músculo cremáster", "En el varón sus fibras inferiores descienden con el cordón espermático al escroto y forman el músculo cremáster (rama genital del nervio genitofemoral)."]], [],
 ["Las fibras del oblicuo interno son perpendiculares a las del externo; en contracción unilateral rota el tronco hacia el mismo lado.", "El oblicuo interno forma el cremáster y parte del tendón conjunto."], ["oblicuo menor", "oblicuo interno"]],
},
"m-transversus-abdominis": {
"en": ["Transversus abdominis", "The deepest muscle of the lateral abdominal wall; its fibres run horizontally and wrap the abdomen like a corset.",
 ["Inner surfaces of costal cartilages 7–12, thoracolumbar fascia, iliac crest, lateral 1/3 of the inguinal ligament", "Linea alba, pubic crest and pectineal line (conjoint tendon)",
  "Intercostal nerves (T7–T11), subcostal nerve, iliohypogastric and ilioinguinal nerves", "Inferior epigastric artery, deep circumflex iliac artery, posterior intercostal arteries",
  "Compresses the abdominal viscera and raises intra-abdominal pressure; contributes to stabilising the lumbar spine (core muscle)"], [],
 ["The TAP (transversus abdominis plane) block is injected into the plane between this muscle and the internal oblique for pain control in abdominal wall surgery."],
 ["Transversus abdominis is the most important muscle for raising intra-abdominal pressure and stabilising the trunk.", "In the TAP block the local anaesthetic is injected between the internal oblique and transversus."], ["transversus", "TAP"]],
"fr": ["Muscle transverse de l'abdomen", "Le plus profond des muscles de la paroi abdominale latérale ; ses fibres horizontales enveloppent l'abdomen comme un corset.",
 ["Face interne des cartilages costaux 7 à 12, fascia thoraco-lombaire, crête iliaque, 1/3 latéral du ligament inguinal", "Ligne blanche, crête pubienne et ligne pectinée (tendon conjoint)",
  "Nerfs intercostaux (T7–T11), nerf subcostal, nerfs ilio-hypogastrique et ilio-inguinal", "Artère épigastrique inférieure, artère circonflexe iliaque profonde, artères intercostales postérieures",
  "Comprime les viscères et augmente la pression intra-abdominale ; participe à la stabilisation du rachis lombaire (muscle du gainage)"], [],
 ["Le bloc TAP (plan du transverse de l'abdomen) est réalisé dans le plan entre ce muscle et l'oblique interne pour l'analgésie en chirurgie pariétale."],
 ["Le transverse est le muscle le plus important pour augmenter la pression abdominale et stabiliser le tronc.", "Dans le bloc TAP, l'anesthésique local est injecté entre l'oblique interne et le transverse."], ["transverse"]],
"de": ["M. transversus abdominis", "Der tiefste Muskel der seitlichen Bauchwand; seine Fasern verlaufen quer und umgeben den Bauch wie ein Korsett.",
 ["Innenfläche der Rippenknorpel 7–12, Fascia thoracolumbalis, Crista iliaca, laterales Drittel des Leistenbands", "Linea alba, Crista pubica und Pecten ossis pubis (Falx inguinalis)",
  "Nn. intercostales (T7–T11), N. subcostalis, N. iliohypogastricus, N. ilioinguinalis", "A. epigastrica inferior, A. circumflexa ilium profunda, Aa. intercostales posteriores",
  "Komprimiert die Bauchorgane und erhöht den Bauchdruck; trägt zur Stabilisierung der Lendenwirbelsäule bei (Core-Muskel)"], [],
 ["Der TAP-Block (Transversus-abdominis-Plane) wird zur Schmerztherapie bei Bauchwandoperationen in die Ebene zwischen diesem Muskel und dem Obliquus internus gesetzt."],
 ["Der Transversus abdominis ist der wichtigste Muskel für Bauchpresse und Rumpfstabilität.", "Beim TAP-Block wird das Lokalanästhetikum zwischen Obliquus internus und Transversus injiziert."], ["querer Bauchmuskel", "Transversus"]],
"es": ["Músculo transverso del abdomen", "El músculo más profundo de la pared abdominal lateral; sus fibras horizontales envuelven el abdomen como un corsé.",
 ["Cara interna de los cartílagos costales 7.º–12.º, fascia toracolumbar, cresta ilíaca, 1/3 lateral del ligamento inguinal", "Línea alba, cresta del pubis y línea pectínea (tendón conjunto)",
  "Nervios intercostales (T7–T11), nervio subcostal, nervios iliohipogástrico e ilioinguinal", "Arteria epigástrica inferior, arteria circunfleja ilíaca profunda, arterias intercostales posteriores",
  "Comprime las vísceras y aumenta la presión intraabdominal; contribuye a estabilizar la columna lumbar (músculo del core)"], [],
 ["El bloqueo TAP (plano del transverso del abdomen) se realiza en el plano entre este músculo y el oblicuo interno para el control del dolor en la cirugía de pared abdominal."],
 ["El transverso es el músculo más importante para aumentar la presión abdominal y estabilizar el tronco.", "En el bloqueo TAP el anestésico local se inyecta entre el oblicuo interno y el transverso."], ["transverso"]],
},
"m-quadratus-lumborum": {
"en": ["Quadratus lumborum", "A quadrilateral muscle of the posterior abdominal wall running between the 12th rib and the hip bone.",
 ["Posterior part of the iliac crest and iliolumbar ligament", "Lower border of the 12th rib and transverse processes of L1–L4", "Subcostal nerve (T12) and anterior rami of L1–L4",
  "Lumbar arteries, subcostal artery, iliolumbar artery", "Bends the trunk to the same side; fixes the 12th rib during inspiration; acting on both sides it extends the lumbar spine"], [],
 ["It is one of the common muscular causes of low back pain."],
 ["A muscle of the posterior abdominal wall, supplied by the subcostal nerve and the anterior rami of L1–L4."], ["QL"]],
"fr": ["Muscle carré des lombes", "Muscle quadrilatère de la paroi abdominale postérieure tendu entre la 12e côte et l'os coxal.",
 ["Partie postérieure de la crête iliaque et ligament ilio-lombaire", "Bord inférieur de la 12e côte et processus transverses de L1–L4", "Nerf subcostal (T12) et rameaux antérieurs de L1–L4",
  "Artères lombaires, artère subcostale, artère ilio-lombaire", "Incline le tronc du même côté ; fixe la 12e côte lors de l'inspiration ; en contraction bilatérale, étend le rachis lombaire"], [],
 ["C'est l'une des causes musculaires fréquentes de lombalgie."],
 ["Muscle de la paroi abdominale postérieure, innervé par le nerf subcostal et les rameaux antérieurs de L1–L4."], ["carré des lombes"]],
"de": ["M. quadratus lumborum", "Viereckiger Muskel der hinteren Bauchwand zwischen 12. Rippe und Hüftbein.",
 ["Hinterer Teil der Crista iliaca und Lig. iliolumbale", "Unterrand der 12. Rippe und Querfortsätze L1–L4", "N. subcostalis (T12) und Rr. anteriores L1–L4",
  "Aa. lumbales, A. subcostalis, A. iliolumbalis", "Neigt den Rumpf zur gleichen Seite; fixiert die 12. Rippe bei der Einatmung; beidseitig streckt er die Lendenwirbelsäule"], [],
 ["Er ist eine der häufigen muskulären Ursachen von Rückenschmerzen."],
 ["Muskel der hinteren Bauchwand, innerviert vom N. subcostalis und den Rr. anteriores L1–L4."], ["Quadratus", "viereckiger Lendenmuskel"]],
"es": ["Músculo cuadrado lumbar", "Músculo cuadrilátero de la pared abdominal posterior situado entre la 12.ª costilla y el coxal.",
 ["Parte posterior de la cresta ilíaca y ligamento iliolumbar", "Borde inferior de la 12.ª costilla y apófisis transversas de L1–L4", "Nervio subcostal (T12) y ramos anteriores de L1–L4",
  "Arterias lumbares, arteria subcostal, arteria iliolumbar", "Inclina el tronco hacia el mismo lado; fija la 12.ª costilla en la inspiración; en acción bilateral extiende la columna lumbar"], [],
 ["Es una de las causas musculares frecuentes de dolor lumbar."],
 ["Músculo de la pared abdominal posterior, inervado por el nervio subcostal y los ramos anteriores de L1–L4."], ["cuadrado lumbar"]],
},
"diaphragma-pelvis": {
"en": ["Pelvic floor muscles", "The funnel-shaped muscular layer forming the floor of the pelvic cavity. It supports the pelvic organs and contributes to continence.",
 ["Levator ani: back of the pubis, tendinous arch of levator ani, ischial spine; coccygeus: ischial spine",
  "Perineal body, anococcygeal ligament, coccyx and lower border of the sacrum", "Nerve to levator ani (S3–S4), branches of the pudendal nerve",
  "Inferior gluteal artery, internal pudendal artery, inferior vesical artery",
  "Supports the pelvic organs and resists rises in intra-abdominal pressure; puborectalis forms the anorectal angle and maintains faecal continence"],
 [["Parts", "Levator ani consists of the puborectalis, pubococcygeus and iliococcygeus. The external anal sphincter is the voluntary sphincter encircling the anal canal."]],
 ["Damage to the pelvic floor muscles in childbirth can cause stress urinary incontinence and pelvic organ prolapse; Kegel exercises strengthen these muscles."],
 ["Levator ani has three parts: puborectalis, pubococcygeus, iliococcygeus; it arises from the tendinous arch of levator ani.", "Levator ani is supplied by the S4 root and branches of the pudendal nerve; birth injury leads to stress incontinence and prolapse."], ["levator ani", "pelvic floor"]],
"fr": ["Muscles du plancher pelvien", "Couche musculaire en entonnoir qui forme le plancher de la cavité pelvienne. Elle soutient les organes pelviens et participe à la continence.",
 ["Élévateur de l'anus : face postérieure du pubis, arc tendineux du muscle élévateur de l'anus, épine ischiatique ; coccygien : épine ischiatique",
  "Centre tendineux du périnée, ligament anococcygien, coccyx et bord inférieur du sacrum", "Nerf du muscle élévateur de l'anus (S3–S4), branches du nerf pudendal",
  "Artère glutéale inférieure, artère pudendale interne, artère vésicale inférieure",
  "Soutient les organes pelviens et s'oppose aux hausses de pression abdominale ; le pubo-rectal forme l'angle anorectal et assure la continence fécale"],
 [["Parties", "L'élévateur de l'anus comprend les muscles pubo-rectal, pubo-coccygien et ilio-coccygien. Le sphincter externe de l'anus est le sphincter volontaire qui entoure le canal anal."]],
 ["Les lésions du plancher pelvien lors de l'accouchement peuvent entraîner une incontinence urinaire d'effort et un prolapsus ; les exercices de Kegel renforcent ces muscles."],
 ["L'élévateur de l'anus comporte trois parties : pubo-rectal, pubo-coccygien, ilio-coccygien ; il naît de l'arc tendineux.", "Il est innervé par la racine S4 et des branches du nerf pudendal ; les lésions obstétricales causent incontinence d'effort et prolapsus."], ["élévateur de l'anus", "périnée"]],
"de": ["Beckenbodenmuskulatur", "Trichterförmige Muskelschicht, die den Boden der Beckenhöhle bildet. Sie stützt die Beckenorgane und trägt zur Kontinenz bei.",
 ["M. levator ani: Rückfläche des Os pubis, Arcus tendineus musculi levatoris ani, Spina ischiadica; M. coccygeus: Spina ischiadica",
  "Centrum tendineum perinei, Lig. anococcygeum, Steißbein und Unterrand des Kreuzbeins", "N. musculi levatoris ani (S3–S4), Äste des N. pudendus",
  "A. glutea inferior, A. pudenda interna, A. vesicalis inferior",
  "Stützt die Beckenorgane und wirkt dem Bauchdruck entgegen; der M. puborectalis bildet den anorektalen Winkel und sichert die Stuhlkontinenz"],
 [["Anteile", "Der M. levator ani besteht aus M. puborectalis, M. pubococcygeus und M. iliococcygeus. Der M. sphincter ani externus ist der willkürliche Schließmuskel um den Analkanal."]],
 ["Geburtsverletzungen der Beckenbodenmuskulatur können zu Belastungsinkontinenz und Beckenorganprolaps führen; Kegel-Übungen stärken diese Muskeln."],
 ["Der Levator ani hat drei Teile: Puborectalis, Pubococcygeus, Iliococcygeus; er entspringt am Arcus tendineus.", "Er wird von der Wurzel S4 und Ästen des N. pudendus innerviert; Geburtsschäden führen zu Belastungsinkontinenz und Prolaps."], ["Levator ani", "Beckenboden"]],
"es": ["Músculos del suelo pélvico", "Capa muscular en forma de embudo que forma el suelo de la cavidad pélvica. Sostiene los órganos pélvicos y contribuye a la continencia.",
 ["Elevador del ano: cara posterior del pubis, arco tendinoso del elevador del ano, espina isquiática; coccígeo: espina isquiática",
  "Cuerpo perineal, ligamento anococcígeo, cóccix y borde inferior del sacro", "Nervio del elevador del ano (S3–S4), ramas del nervio pudendo",
  "Arteria glútea inferior, arteria pudenda interna, arteria vesical inferior",
  "Sostiene los órganos pélvicos y resiste los aumentos de presión abdominal; el puborrectal forma el ángulo anorrectal y mantiene la continencia fecal"],
 [["Porciones", "El elevador del ano está formado por el puborrectal, el pubococcígeo y el iliococcígeo. El esfínter anal externo es el esfínter voluntario que rodea el conducto anal."]],
 ["La lesión del suelo pélvico en el parto puede causar incontinencia urinaria de esfuerzo y prolapso de órganos pélvicos; los ejercicios de Kegel fortalecen estos músculos."],
 ["El elevador del ano tiene tres porciones: puborrectal, pubococcígeo e iliococcígeo; nace del arco tendinoso.", "Lo inervan la raíz S4 y ramas del pudendo; la lesión obstétrica produce incontinencia de esfuerzo y prolapso."], ["elevador del ano", "suelo pélvico"]],
},
"linea-alba": {
"en": ["Linea alba", "A fibrous band in the midline of the anterior abdominal wall, running from the xiphoid process to the pubic symphysis and formed by the fusion of the aponeuroses of the lateral abdominal muscles. The umbilicus (umbilical ring) lies on it.",
 ["Interlacing in the midline of the aponeuroses of the external oblique, internal oblique and transversus abdominis", "Xiphoid process – pubic symphysis"], [],
 ["Because it is avascular, midline incisions (laparotomy) are made here.", "Epigastric hernias develop through gaps in the linea alba."],
 ["The linea alba is wide above the umbilicus and narrow below it; diastasis recti is separation of the rectus muscles in this region."], []],
"fr": ["Ligne blanche", "Bande fibreuse médiane de la paroi abdominale antérieure, du processus xiphoïde à la symphyse pubienne, formée par l'union des aponévroses des muscles larges de l'abdomen. L'ombilic (anneau ombilical) se trouve sur elle.",
 ["Entrecroisement sur la ligne médiane des aponévroses de l'oblique externe, de l'oblique interne et du transverse", "Processus xiphoïde – symphyse pubienne"], [],
 ["Étant avasculaire, elle est le siège des incisions médianes (laparotomie).", "Les hernies épigastriques se développent à travers des orifices de la ligne blanche."],
 ["La ligne blanche est large au-dessus de l'ombilic et étroite en dessous ; le diastasis des grands droits est leur écartement dans cette région."], ["linea alba"]],
"de": ["Linea alba", "Bindegewebiger Streifen in der Mittellinie der vorderen Bauchwand vom Processus xiphoideus zur Symphyse, entstanden aus der Verflechtung der Aponeurosen der seitlichen Bauchmuskeln. Der Nabel (Anulus umbilicalis) liegt auf ihr.",
 ["Verflechtung der Aponeurosen von M. obliquus externus, M. obliquus internus und M. transversus abdominis in der Mittellinie", "Processus xiphoideus – Symphysis pubica"], [],
 ["Da sie gefäßarm ist, werden hier Mittellinienschnitte (Laparotomie) angelegt.", "Epigastrische Hernien entstehen durch Lücken in der Linea alba."],
 ["Die Linea alba ist oberhalb des Nabels breit, unterhalb schmal; die Rektusdiastase ist das Auseinanderweichen der Rektusmuskeln in diesem Bereich."], ["weiße Linie"]],
"es": ["Línea alba", "Banda fibrosa en la línea media de la pared abdominal anterior, de la apófisis xifoides a la sínfisis del pubis, formada por la fusión de las aponeurosis de los músculos anchos del abdomen. El ombligo (anillo umbilical) está sobre ella.",
 ["Entrecruzamiento en la línea media de las aponeurosis del oblicuo externo, el oblicuo interno y el transverso", "Apófisis xifoides – sínfisis del pubis"], [],
 ["Al ser avascular, las incisiones de línea media (laparotomía) se hacen aquí.", "Las hernias epigástricas se forman a través de orificios de la línea alba."],
 ["La línea alba es ancha por encima del ombligo y estrecha por debajo; la diástasis de rectos es su separación en esta zona."], ["línea blanca"]],
},
"lig-inguinale": {
"en": ["Inguinal ligament", "The rolled-under lower border of the external oblique aponeurosis, running between the anterior superior iliac spine and the pubic tubercle. It marks the boundary between the abdomen and the thigh.",
 ["ASIS – pubic tubercle", "Muscular lacuna: iliopsoas and femoral nerve; vascular lacuna: femoral artery and vein, femoral canal (lymphatics)", "Forms the floor of the inguinal canal"],
 [["Femoral triangle", "In the triangle bounded by the inguinal ligament (above), sartorius (laterally) and adductor longus (medially) lie, from lateral to medial, the nerve, artery, vein and lymphatics (NAVeL)."]],
 ["Inguinal hernias are felt above the ligament, femoral hernias below it and lateral to and below the pubic tubercle.", "The femoral pulse is taken just below the midpoint of the ligament."],
 ["The lacunar ligament (Gimbernat's) runs from the medial end of the inguinal ligament to the pecten pubis and forms the medial border of the femoral canal.", "A femoral hernia is felt below the inguinal ligament, below and lateral to the pubic tubercle; it is more common in women."], ["Poupart's ligament", "groin"]],
"fr": ["Ligament inguinal", "Bord inférieur enroulé de l'aponévrose de l'oblique externe, tendu de l'épine iliaque antéro-supérieure au tubercule pubien. Il marque la limite entre l'abdomen et la cuisse.",
 ["EIAS – tubercule pubien", "Lacune musculaire : ilio-psoas et nerf fémoral ; lacune vasculaire : artère et veine fémorales, canal fémoral (lymphatiques)", "Forme le plancher du canal inguinal"],
 [["Trigone fémoral", "Dans le triangle limité par le ligament inguinal (en haut), le sartorius (en dehors) et le long adducteur (en dedans) se trouvent, de dehors en dedans, le nerf, l'artère, la veine et les lymphatiques."]],
 ["Les hernies inguinales se palpent au-dessus du ligament, les hernies fémorales en dessous, en dehors et au-dessous du tubercule pubien.", "Le pouls fémoral se prend juste sous le milieu du ligament."],
 ["Le ligament lacunaire (de Gimbernat) va de l'extrémité médiale du ligament inguinal au pecten du pubis et forme la limite médiale du canal fémoral.", "La hernie fémorale se palpe sous le ligament inguinal, au-dessous et en dehors du tubercule pubien ; elle est plus fréquente chez la femme."], ["arcade crurale", "aine"]],
"de": ["Leistenband", "Der eingerollte Unterrand der Aponeurose des äußeren schrägen Bauchmuskels zwischen Spina iliaca anterior superior und Tuberculum pubicum. Es bildet die Grenze zwischen Bauch und Oberschenkel.",
 ["SIAS – Tuberculum pubicum", "Lacuna musculorum: M. iliopsoas und N. femoralis; Lacuna vasorum: A. und V. femoralis, Canalis femoralis (Lymphgefäße)", "Bildet den Boden des Leistenkanals"],
 [["Trigonum femorale", "Im Dreieck zwischen Leistenband (oben), M. sartorius (lateral) und M. adductor longus (medial) liegen von lateral nach medial Nerv, Arterie, Vene und Lymphgefäße (IVAN von medial)."]],
 ["Leistenhernien tastet man oberhalb des Bandes, Schenkelhernien unterhalb davon, lateral und unterhalb des Tuberculum pubicum.", "Der Femoralispuls wird direkt unterhalb der Bandmitte getastet."],
 ["Das Lig. lacunare (Gimbernat) zieht vom medialen Ende des Leistenbands zum Pecten ossis pubis und bildet die mediale Grenze des Schenkelkanals.", "Eine Schenkelhernie tastet man unterhalb des Leistenbands, unter und lateral vom Tuberculum pubicum; sie ist bei Frauen häufiger."], ["Lig. inguinale", "Leiste"]],
"es": ["Ligamento inguinal", "Borde inferior replegado de la aponeurosis del oblicuo externo, entre la espina ilíaca anterosuperior y el tubérculo del pubis. Marca el límite entre el abdomen y el muslo.",
 ["EIAS – tubérculo del pubis", "Laguna muscular: iliopsoas y nervio femoral; laguna vascular: arteria y vena femorales, conducto femoral (linfáticos)", "Forma el suelo del conducto inguinal"],
 [["Triángulo femoral", "En el triángulo limitado por el ligamento inguinal (arriba), el sartorio (lateral) y el aductor largo (medial) se encuentran, de lateral a medial, nervio, arteria, vena y linfáticos (NAVeL)."]],
 ["Las hernias inguinales se palpan por encima del ligamento; las femorales, por debajo, lateral e inferior al tubérculo del pubis.", "El pulso femoral se toma justo por debajo del punto medio del ligamento."],
 ["El ligamento lacunar (de Gimbernat) va del extremo medial del ligamento inguinal a la cresta pectínea y forma el límite medial del conducto femoral.", "La hernia femoral se palpa por debajo del ligamento inguinal, inferior y lateral al tubérculo del pubis; es más frecuente en mujeres."], ["arco crural", "ingle"]],
},
"fascia-thoracolumbalis": {
"en": ["Thoracolumbar fascia", "A strong fascial layer enclosing the deep back muscles, arranged in three layers in the lumbar region. It provides attachment for latissimus dorsi and the abdominal muscles.",
 ["Anterior (in front of quadratus lumborum), middle (between quadratus lumborum and erector spinae) and posterior layer (behind erector spinae)",
  "Latissimus dorsi, internal oblique, transversus abdominis, serratus posterior inferior"], [],
 ["Tension and inflammation of the fascia may play a role in low back pain."],
 ["The posterior layer of the thoracolumbar fascia fuses with the aponeurosis of latissimus dorsi."], ["lumbodorsal fascia"]],
"fr": ["Fascia thoraco-lombaire", "Fascia solide qui enveloppe les muscles profonds du dos et se dispose en trois feuillets dans la région lombaire. Il donne insertion au grand dorsal et aux muscles abdominaux.",
 ["Antérieur (en avant du carré des lombes), moyen (entre carré des lombes et érecteur du rachis) et postérieur (en arrière de l'érecteur du rachis)",
  "Grand dorsal, oblique interne, transverse de l'abdomen, dentelé postérieur inférieur"], [],
 ["La tension et l'inflammation du fascia peuvent participer aux lombalgies."],
 ["Le feuillet postérieur du fascia thoraco-lombaire fusionne avec l'aponévrose du grand dorsal."], ["aponévrose lombaire"]],
"de": ["Fascia thoracolumbalis", "Kräftige Faszie, die die tiefen Rückenmuskeln umhüllt und im Lendenbereich drei Blätter bildet. Sie dient Latissimus dorsi und Bauchmuskeln als Ursprung.",
 ["Vorderes (vor dem Quadratus lumborum), mittleres (zwischen Quadratus lumborum und Erector spinae) und hinteres Blatt (hinter dem Erector spinae)",
  "M. latissimus dorsi, M. obliquus internus abdominis, M. transversus abdominis, M. serratus posterior inferior"], [],
 ["Spannung und Entzündung der Faszie können bei Rückenschmerzen eine Rolle spielen."],
 ["Das hintere Blatt der Fascia thoracolumbalis verschmilzt mit der Aponeurose des Latissimus dorsi."], ["Lumbalfaszie"]],
"es": ["Fascia toracolumbar", "Fascia resistente que envuelve los músculos profundos de la espalda y se dispone en tres hojas en la región lumbar. Da inserción al dorsal ancho y a los músculos abdominales.",
 ["Anterior (delante del cuadrado lumbar), media (entre el cuadrado lumbar y el erector de la columna) y posterior (detrás del erector de la columna)",
  "Dorsal ancho, oblicuo interno, transverso del abdomen, serrato posterior inferior"], [],
 ["La tensión y la inflamación de la fascia pueden intervenir en el dolor lumbar."],
 ["La hoja posterior de la fascia toracolumbar se fusiona con la aponeurosis del dorsal ancho."], ["fascia lumbodorsal"]],
},
"m-deltoideus": {
"en": ["Deltoid", "The thick triangular muscle that forms the rounded contour of the shoulder. It has anterior (clavicular), middle (acromial) and posterior (spinal) parts.",
 ["Lateral 1/3 of the clavicle, acromion and spine of the scapula", "Deltoid tuberosity of the humerus", "Axillary nerve (C5–C6)",
  "Posterior circumflex humeral artery, deltoid branch of the thoraco-acromial artery",
  "Middle part: abducts the arm from 15° up to 90°; anterior part: flexion and internal rotation; posterior part: extension and external rotation"], [],
 ["In a fracture of the surgical neck of the humerus or a shoulder dislocation, axillary nerve injury paralyses deltoid and flattens the shoulder, with sensory loss over the outer shoulder (regimental badge area).",
  "It is a common site for intramuscular injections, given 2–3 fingerbreadths below the acromion to protect the axillary nerve."],
 ["The anterior fibres of deltoid flex and internally rotate, the posterior fibres extend and externally rotate.", "The axillary nerve runs on the deep surface of deltoid about 5 cm below the acromion."], ["deltoid", "delts"]],
"fr": ["Muscle deltoïde", "Muscle épais et triangulaire qui forme le galbe arrondi de l'épaule. Il comporte des parties antérieure (claviculaire), moyenne (acromiale) et postérieure (spinale).",
 ["1/3 latéral de la clavicule, acromion et épine de la scapula", "Tubérosité deltoïdienne de l'humérus", "Nerf axillaire (C5–C6)",
  "Artère circonflexe postérieure de l'humérus, rameau deltoïdien de l'artère thoraco-acromiale",
  "Partie moyenne : abduction du bras de 15° à 90° ; partie antérieure : flexion et rotation médiale ; partie postérieure : extension et rotation latérale"], [],
 ["Lors d'une fracture du col chirurgical de l'humérus ou d'une luxation de l'épaule, une lésion du nerf axillaire paralyse le deltoïde, aplatit le moignon de l'épaule et entraîne une anesthésie de la face latérale de l'épaule (zone du « galon »).",
  "C'est un site fréquent d'injection intramusculaire, réalisée 2–3 travers de doigt sous l'acromion pour épargner le nerf axillaire."],
 ["Les fibres antérieures du deltoïde fléchissent et tournent en dedans, les postérieures étendent et tournent en dehors.", "Le nerf axillaire chemine à la face profonde du deltoïde, environ 5 cm sous l'acromion."], ["deltoïde"]],
"de": ["M. deltoideus", "Kräftiger dreieckiger Muskel, der die runde Schulterkontur bildet. Er hat eine Pars clavicularis (vorn), acromialis (Mitte) und spinalis (hinten).",
 ["Laterales Drittel der Clavicula, Acromion und Spina scapulae", "Tuberositas deltoidea humeri", "N. axillaris (C5–C6)",
  "A. circumflexa humeri posterior, R. deltoideus der A. thoracoacromialis",
  "Pars acromialis: Abduktion des Arms ab 15° bis 90°; Pars clavicularis: Flexion und Innenrotation; Pars spinalis: Extension und Außenrotation"], [],
 ["Bei einer Fraktur des Collum chirurgicum humeri oder einer Schulterluxation führt eine Schädigung des N. axillaris zur Deltoideuslähmung, abgeflachten Schulter und Gefühlsstörung an der Schulteraußenseite.",
  "Er ist ein häufiger Ort für intramuskuläre Injektionen, die 2–3 Querfinger unterhalb des Acromions erfolgen, um den N. axillaris zu schonen."],
 ["Die vorderen Fasern des Deltoideus beugen und innenrotieren, die hinteren strecken und außenrotieren.", "Der N. axillaris verläuft an der Tiefenfläche des Deltoideus etwa 5 cm unterhalb des Acromions."], ["Deltamuskel", "Deltoideus"]],
"es": ["Músculo deltoides", "Músculo grueso y triangular que forma el contorno redondeado del hombro. Tiene porciones anterior (clavicular), media (acromial) y posterior (espinal).",
 ["1/3 lateral de la clavícula, acromion y espina de la escápula", "Tuberosidad deltoidea del húmero", "Nervio axilar (C5–C6)",
  "Arteria circunfleja humeral posterior, rama deltoidea de la arteria toracoacromial",
  "Porción media: abduce el brazo de 15° hasta 90°; anterior: flexión y rotación interna; posterior: extensión y rotación externa"], [],
 ["En la fractura del cuello quirúrgico del húmero o la luxación de hombro, la lesión del nervio axilar paraliza el deltoides, aplana el hombro y causa pérdida sensitiva en la cara lateral del hombro (zona de la charretera).",
  "Es un lugar frecuente de inyección intramuscular, a 2–3 traveses de dedo por debajo del acromion para proteger el nervio axilar."],
 ["Las fibras anteriores del deltoides flexionan y rotan internamente; las posteriores extienden y rotan externamente.", "El nervio axilar discurre por la cara profunda del deltoides, unos 5 cm por debajo del acromion."], ["deltoides"]],
},
}
